style.css:
/* Efeito de Shader / Pós-Processamento via CSS para o Navegador */

body {
  /* Cores mais vibrantes e contraste alto */
  filter: contrast(115%) saturate(130%) brightness(105%) !important;
}

/* Criar efeito de Vinheta (sombras suaves nos cantos da tela) */
body::after {
  content: "" !important;
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  box-shadow: inset 0 0 100px rgba(0, 0, 0, 0.6) !important;
  pointer-events: none !important; /* Permite clicar nos botões normalmente */
  z-index: 999999 !important;
}

/* Brilho Neon / Glow nos botões da página */
button, input[type="button"], input[type="submit"] {
  transition: all 0.3s ease !important;
}

button:hover {
  box-shadow: 0 0 15px rgba(0, 255, 200, 0.6) !important;
  filter: brightness(1.2) !important;
}
